INSERT INTO `ai_chat_messages` VALUES (38, 1, 'assistant', 'text', '我已经收到你的问题：**我想学java开发，能给一条学习路线吗？**。\n\n当前多智能体链路有部分节点暂时没有稳定返回，但我仍可以继续帮你。你可以把问题再具体一点，比如贴出题目、报错、目标课程，或者直接说你想要：学习路径、资源推荐、答疑、学习评估。', 2, 100, NULL, NULL, '2026-05-01 09:57:19');
