INSERT INTO `ai_workflow_runs` VALUES (91, 1, 'agent_resource_generation', 'learning_goal', NULL, 'success', '{\"current_level\": \"beginner\", \"learning_goal\": \"请围绕“后端开发”生成 3 条不同风格的学习路线，适合 beginner 学习者，\\n每周可投入 6 小时，资源偏好为 mixed。\\n\\n请在 path_plan 字段中直接输出以下 JSON，不要使用 Markdown 代码块：\\n{\\n  \\\"route_options\\\": [\\n    {\\n      \\\"route_code\\\": \\\"string\\\",\\n      \\\"title\\\": \\\"string\\\",\\n      \\\"summary\\\": \\\"string\\\",\\n      \\\"fit_reason\\\": \\\"string\\\",\\n      \\\"difficulty\\\": \\\"beginner|intermediate|advanced\\\",\\n      \\\"estimated_weeks\\\": 8,\\n      \\\"stages\\\": [\\n        {\\n          \\\"stage_code\\\": \\\"string\\\",\\n          \\\"title\\\": \\\"string\\\",\\n          \\\"goal\\\": \\\"string\\\",\\n          \\\"description\\\": \\\"string\\\",\\n          \\\"estimated_hours\\\": 8,\\n          \\\"recommended_reason\\\": \\\"string\\\",\\n          \\\"assessment\\\": {\\n            \\\"mode\\\": \\\"generated_quiz\\\",\\n            \\\"question_count\\\": 6,\\n            \\\"pass_score\\\": 70\\n          }\\n        }\\n      ]\\n    }\\n  ]\\n}\\n\\n补充约束：\\n- 每条路线 3 到 4 个阶段。\\n- 路线之间风格要不同，例如“稳扎稳打”“练习驱动”“项目实战”。\\n- 重点关注这些待提升维度：前端开发、编程基础。\"}', '{\"path_plan\": {\"raw\": \"## Learning Path\\n### Stage 1: Core Basics\\n- Environment setup\\n- Variables, data types, and input/output\\n- Conditions and loops\\n\\n### Stage 2: Structured Programming\\n- Functions\\n- Common data structures\\n- File handling and exceptions\\n\\n### Stage 3: Project Practice\\n- Finish one small project end-to-end\\n- Review and iterate every week\"}, \"adjustments\": {\"raw\": \"## Dynamic Adjustments\\n1. If the first two weeks feel difficult, extend the basics stage by one extra week.\\n2. If you can study two hours daily, enter project practice earlier.\\n3. If your goal is job readiness, start building project output early.\\n4. If you get stuck on one concept for more than 2-3 days, switch to a nearby topic and come back later.\"}, \"goal_analysis\": {\"raw\": \"## Goal Analysis\\nYour current goal is **请围绕“后端开发”生成 3 条不同风格的学习路线，适合 beginner 学习者，\\n每周可投入 6 小时，资源偏好为 mixed。\\n\\n请在 path_plan 字段中直接输出以下 JSON，不要使用 Markdown 代码块：\\n{\\n  \\\"route_options\\\": [\\n    {\\n      \\\"route_code\\\": \\\"string\\\",\\n      \\\"title\\\": \\\"string\\\",\\n      \\\"summary\\\": \\\"string\\\",\\n      \\\"fit_reason\\\": \\\"string\\\",\\n      \\\"difficulty\\\": \\\"beginner|intermediate|advanced\\\",\\n      \\\"estimated_weeks\\\": 8,\\n      \\\"stages\\\": [\\n        {\\n          \\\"stage_code\\\": \\\"string\\\",\\n          \\\"title\\\": \\\"string\\\",\\n          \\\"goal\\\": \\\"string\\\",\\n          \\\"description\\\": \\\"string\\\",\\n          \\\"estimated_hours\\\": 8,\\n          \\\"recommended_reason\\\": \\\"string\\\",\\n          \\\"assessment\\\": {\\n            \\\"mode\\\": \\\"generated_quiz\\\",\\n            \\\"question_count\\\": 6,\\n            \\\"pass_score\\\": 70\\n          }\\n        }\\n      ]\\n    }\\n  ]\\n}\\n\\n补充约束：\\n- 每条路线 3 到 4 个阶段。\\n- 路线之间风格要不同，例如“稳扎稳打”“练习驱动”“项目实战”。\\n- 重点关注这些待提升维度：前端开发、编程基础。**.\\n\\nBased on your current level (`beginner`), you should first build solid fundamentals, then move into functions, data structures, and small projects.\"}, \"quality_score\": 0.55, \"generated_content\": {\"content\": \"## Recommended Resources\\n- Official documentation\\n- One complete beginner course\\n- One practice platform\\n- One project-based tutorial\"}}', NULL, '2026-05-02 08:03:39', '2026-05-02 08:03:52', '2026-05-02 08:03:39', '2026-05-02 08:03:52');
