INSERT INTO `ai_workflow_runs` VALUES (95, 7, 'agent_feature_extraction', 'skill_profile', 3, 'success', '{\"source_type\": \"skill_profile\", \"source_ref_id\": 3}', '{\"quality_report\": {\"raw\": \"无图像输入，仅文本评测数据，输入质量良好。\"}, \"dialogue_analysis\": {\"raw\": \"当前无对话记录，无法提取对话特征。\"}, \"six_dimension_profile\": {\"raw\": \"基于评测数据生成六维态画像：\\n- 知识（Knowledge）：编程基础72分（百分位77%）、数据库82分（百分位87%），平均77分，等级intermediate，知识体系较扎实，数据库表现突出。\\n- 逻辑（Logic）：算法思维77分（百分位82%），等级intermediate，逻辑推理能力稳定。\\n- 表达（Expression）：前端开发69分（百分位74%），等级foundation，表达能力相对薄弱，需加强实践。\\n- 习惯（Habit）：无直接数据，但学习自驱74分（百分位79%）反映良好学习习惯，等级intermediate。\\n- 动机（Motivation）：学习自驱74分（百分位79%），等级intermediate，内在动机较强。\\n- 反思（Reflection）：无直接数据，整体表现稳定，建议结合项目练习持续巩固。\", \"dimensions\": [\"knowledge\", \"logic\", \"expression\", \"habit\", \"motivation\", \"reflection\"]}}', NULL, '2026-05-02 11:04:15', '2026-05-02 11:04:21', '2026-05-02 11:04:15', '2026-05-02 11:04:21');
INSERT INTO `ai_workflow_runs` VALUES (96, 7, 'agent_learning_evaluation', 'learning_evaluation', NULL, 'success', '{\"month\": null}', '{\"diagnosis\": {\"raw\": \"本周学习投入极低，总学习时长仅2分钟，活跃天数1天，远低于有效学习阈值。无任何练习或课程完成，学习行为几乎为零。虽然技能快照总分74.8（排名75%）表明用户具备一定基础，但本周未转化为实际学习行动，专注率仅13.72%，学习效率极低。整体处于停滞状态，缺乏持续学习动力和习惯。\"}, \"optimization\": {\"raw\": \"1. 设定每日最小学习目标（如5分钟），利用平台提醒功能强制启动。2. 推荐短小精悍的互动式编程练习（如代码闯关），降低启动门槛。3. 启动连续打卡奖励机制，连续3天学习可解锁徽章或额外积分。4. 引导用户设置具体学习目标（如“本周完成一门微型课程”），并定期推送进度反馈。5. 考虑从技能快照中识别薄弱点，定制1-2个针对性练习任务。\"}, \"report_content\": {\"overview\": \"## 📊 学习周报（2026-04-26 ~ 2026-05-02）\\n\\n### 📌 总体表现\\n- **学习时长**：2分钟（仅1天活跃）\\n- **专注率**：13.72%（极低）\\n- **完成观看**：1个（平均进度13.81%）\\n- **练习/课程**：无任何练习或课程完成\\n\\n### 🧠 能力现状\\n- **技能总分**：74.8（超过75%的用户）\\n- **主要方向**：编程（96.4%）、数据库（3.6%）\\n- **路径进度**：0%（未开始）\\n\\n### ⚠️ 诊断与建议\\n本周学习几乎空白，虽然你的技能基础不错，但“知道”不等于“做到”。建议从以下步骤开始：\\n1. **每天5分钟**：打开一个编程短视频或完成一道简单练习题。\\n2. **设置提醒**：开启每日学习提醒，固定时间段学习。\\n3. **小目标奖励**：连续学习3天即可获得“起步者”徽章。\\n\\n### 🎯 下周目标\\n- 学习时长 ≥ 30分钟\\n- 完成至少1次互动练习\\n- 连续学习天数 ≥ 3天\\n\\n> 你的潜力很大，行动才是关键！加油 💪\", \"detailed_report\": \"## 📊 学习周报（2026-04-26 ~ 2026-05-02）\\n\\n### 📌 总体表现\\n- **学习时长**：2分钟（仅1天活跃）\\n- **专注率**：13.72%（极低）\\n- **完成观看**：1个（平均进度13.81%）\\n- **练习/课程**：无任何练习或课程完成\\n\\n### 🧠 能力现状\\n- **技能总分**：74.8（超过75%的用户）\\n- **主要方向**：编程（96.4%）、数据库（3.6%）\\n- **路径进度**：0%（未开始）\\n\\n### ⚠️ 诊断与建议\\n本周学习几乎空白，虽然你的技能基础不错，但“知道”不等于“做到”。建议从以下步骤开始：\\n1. **每天5分钟**：打开一个编程短视频或完成一道简单练习题。\\n2. **设置提醒**：开启每日学习提醒，固定时间段学习。\\n3. **小目标奖励**：连续学习3天即可获得“起步者”徽章。\\n\\n### 🎯 下周目标\\n- 学习时长 ≥ 30分钟\\n- 完成至少1次互动练习\\n- 连续学习天数 ≥ 3天\\n\\n> 你的潜力很大，行动才是关键！加油 💪\"}, \"recommendations\": [{\"type\": \"optimization\", \"title\": \"下一轮优化建议\", \"description\": \"1. 设定每日最小学习目标（如5分钟），利用平台提醒功能强制启动。2. 推荐短小精悍的互动式编程练习（如代码闯关），降低启动门槛。3. 启动连续打卡奖励机制，连续3天学习可解锁徽章或额外积分。4. 引导用户设置具体学习目标（如“本周完成一门微型课程”），并定期推送进度反馈。5. 考虑从技能快照中识别薄弱点，定制1-2个针对性练习任务。\"}], \"learner_portrait\": {\"raw\": \"用户 lijie 属于低活跃学习者，无明确职业或学习目标，连续学习天数为0。偏好编程方向（占96.4%），但投入严重不足。技能基础尚可（74.8分），但学习行为与能力脱节，可能处于“知道但不动”的阶段。需要从建立最小学习习惯入手，逐步提升参与度。\"}}', NULL, '2026-05-02 11:04:42', '2026-05-02 11:04:53', '2026-05-02 11:04:42', '2026-05-02 11:04:53');
