-- ----------------------------
-- Table structure for questions
-- ----------------------------
DROP TABLE IF EXISTS `questions`;
CREATE TABLE `questions`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `bank_id` bigint UNSIGNED NOT NULL COMMENT '题库ID',
  `category_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '分类ID',
  `course_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '课程ID',
  `lesson_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '课时ID',
  `question_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'single_choice' COMMENT '题目类型',
  `difficulty` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'medium' COMMENT '难度等级',
  `stem` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '题干',
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '答案解析',
  `correct_answer_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '正确答案文本',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'published' COMMENT '状态',
  `sort_order` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_questions_bank_status_difficulty`(`bank_id` ASC, `status` ASC, `difficulty` ASC) USING BTREE,
  INDEX `idx_questions_course_lesson`(`course_id` ASC, `lesson_id` ASC) USING BTREE,
  INDEX `idx_questions_category_type`(`category_id` ASC, `question_type` ASC) USING BTREE,
  CONSTRAINT `fk_questions_bank_id` FOREIGN KEY (`bank_id`) REFERENCES `question_banks` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_questions_category_id` FOREIGN KEY (`category_id`) REFERENCES `content_categories` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_questions_course_id` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '题库题目表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of questions
-- ----------------------------
INSERT INTO `questions` VALUES (1, 1, NULL, NULL, NULL, 'single_choice', 'easy', 'Python中哪个关键字用于定义函数？', '在Python中，def关键字用于定义函数', NULL, 'published', 1, '2026-05-01 14:39:57', '2026-05-01 14:39:57');
INSERT INTO `questions` VALUES (2, 1, NULL, NULL, NULL, 'single_choice', 'easy', '以下哪个是Python的可变数据类型？', 'list是可变的，可以修改其元素', NULL, 'published', 2, '2026-05-01 14:39:57', '2026-05-01 14:39:57');
INSERT INTO `questions` VALUES (3, 1, NULL, NULL, NULL, 'multiple_choice', 'medium', 'Python中的不可变数据类型包括？', 'tuple、str、int都是不可变类型', NULL, 'published', 3, '2026-05-01 14:39:57', '2026-05-01 14:39:57');
INSERT INTO `questions` VALUES (4, 4, 5, NULL, NULL, 'single_choice', 'easy', '根据视频中“基础篇”的课程内容，下列哪个主题不属于初级工程师的学习范围？', '视频中基础篇明确列出了MySQL概述、SQL、函数、约束、多表查询和事务，而索引属于进阶篇的内容。', 'B', 'published', 1, '2026-05-02 14:40:06', '2026-05-02 14:40:06');
INSERT INTO `questions` VALUES (5, 4, 5, NULL, NULL, 'single_choice', 'easy', '视频中开发者与数据库之间的交互语言是？', '视频中的图示明确标注开发者通过SQL与数据库通信，SQL是关系型数据库的标准查询语言。', 'C', 'published', 2, '2026-05-02 14:40:06', '2026-05-02 14:40:06');
INSERT INTO `questions` VALUES (6, 4, 5, NULL, NULL, 'single_choice', 'easy', 'MySQL属于以下哪种类型的软件？', 'MySQL是一个关系型数据库管理系统（DBMS），用于管理数据库，而非仅仅一个数据库或操作系统。', 'B', 'published', 3, '2026-05-02 14:40:07', '2026-05-02 14:40:07');
INSERT INTO `questions` VALUES (7, 4, 5, NULL, NULL, 'single_choice', 'medium', '视频将MySQL学习路径分为三个部分：基础篇、____篇和运维篇。空缺处应填？', '视频中明确展示了三个列：基础篇、进阶篇、运维篇，进阶篇包含索引、锁等深入内容。', 'A', 'published', 4, '2026-05-02 14:40:07', '2026-05-02 14:40:07');
INSERT INTO `questions` VALUES (8, 4, 5, NULL, NULL, 'single_choice', 'medium', '在基础篇中，学习完SQL和函数之后，接下来的两个主题是____和多表查询。空缺处应填？', '视频右侧渐进列表显示：MySQL概述 → SQL → 函数 → 约束 → 多表查询，因此约束是紧接的下一主题。', 'A', 'published', 5, '2026-05-02 14:40:07', '2026-05-02 14:40:07');
INSERT INTO `questions` VALUES (9, 4, 5, NULL, NULL, 'single_choice', 'hard', '为什么视频将“事务”和“多表查询”放在基础篇，而将“索引”和“锁”放在进阶篇？以下解释最合理的是？', '基础篇面向初级工程师，重点是正确实现功能；事务和多表查询是日常基础操作。索引和锁涉及性能优化和并发控制，需要更深入理解数据库内部机制，属于进阶内容。', 'B', 'published', 6, '2026-05-02 14:40:08', '2026-05-02 14:40:08');
INSERT INTO `questions` VALUES (10, 5, NULL, NULL, NULL, 'single_choice', 'easy', '快速导读阶段的主要目标是什么？', '该阶段的核心是建立主题地图，明确知识边界和常见题型，而非深入细节或完成项目。', 'B', 'published', 1, '2026-05-02 16:06:01', '2026-05-02 16:06:01');
INSERT INTO `questions` VALUES (11, 5, NULL, NULL, NULL, 'single_choice', 'easy', '阶段说明中“先了解知识全貌，再进入高频练习”的主要好处是什么？', '先看全局，练习时更容易抓重点，避免盲目练习。', 'B', 'published', 2, '2026-05-02 16:06:01', '2026-05-02 16:06:01');
INSERT INTO `questions` VALUES (12, 5, NULL, NULL, NULL, 'single_choice', 'easy', '推荐的参考资源 MDN 学习资源覆盖哪些领域？', 'MDN 学习资源覆盖 Web 开发的全貌，包括前端和后端技术（如 Node.js）。', 'C', 'published', 3, '2026-05-02 16:06:02', '2026-05-02 16:06:02');
INSERT INTO `questions` VALUES (13, 5, NULL, NULL, NULL, 'single_choice', 'easy', '在快速导读阶段，学习者最应该做什么？', '该阶段强调先建立整体认知，了解知识全貌，而非立即深入细节或大量练习。', 'B', 'published', 4, '2026-05-02 16:06:03', '2026-05-02 16:06:03');
INSERT INTO `questions` VALUES (14, 6, NULL, NULL, NULL, 'single_choice', 'easy', '在 HTTP 协议中，GET 和 POST 请求的主要区别是什么？', 'GET 请求用于获取资源，参数附加在 URL 中，有长度限制且不安全；POST 请求用于提交数据，参数放在请求体中，更安全且无长度限制。', 'B', 'published', 1, '2026-05-02 19:09:28', '2026-05-02 19:09:28');
INSERT INTO `questions` VALUES (15, 6, NULL, NULL, NULL, 'single_choice', 'easy', '以下哪个是 URL 的正确组成部分？', '一个完整的 URL 通常包含协议、主机名、端口（可选）、路径、查询参数（可选）和片段（可选）。', 'A', 'published', 2, '2026-05-02 19:09:29', '2026-05-02 19:09:29');
INSERT INTO `questions` VALUES (16, 6, NULL, NULL, NULL, 'single_choice', 'easy', '在客户端-服务器模型中，以下哪项描述是正确的？', '客户端发起请求，服务器接收请求并返回响应。服务器是提供资源的中心，客户端是请求资源的终端。', 'C', 'published', 3, '2026-05-02 19:09:29', '2026-05-02 19:09:29');
INSERT INTO `questions` VALUES (17, 6, NULL, NULL, NULL, 'single_choice', 'medium', '在本地开发环境中，使用 Python 内置模块启动一个简单的 HTTP 服务器的正确命令是？', 'Python 3 使用 `python -m http.server` 启动当前目录的 HTTP 服务器，默认端口为 8000。', 'A', 'published', 4, '2026-05-02 19:09:30', '2026-05-02 19:09:30');
INSERT INTO `questions` VALUES (18, 6, NULL, NULL, NULL, 'single_choice', 'easy', '在命令行中，用于列出当前目录下所有文件和文件夹的命令是？', '在 Unix/Linux/macOS 中使用 `ls`，在 Windows 中使用 `dir`。本题假设通用 Unix 环境。', 'A', 'published', 5, '2026-05-02 19:09:30', '2026-05-02 19:09:30');

-- ----------------------------
-- Table structure for report_achievements
-- ----------------------------
DROP TABLE IF EXISTS `report_achievements`;
CREATE TABLE `report_achievements`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `report_id` bigint UNSIGNED NOT NULL COMMENT '报告ID',
  `title` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '描述',
  `icon` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图标',
  `color_token` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '颜色标识',
  `sort_order` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '排序值',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_report_achievements_report_sort`(`report_id` ASC, `sort_order` ASC) USING BTREE,
  CONSTRAINT `fk_report_achievements_report_id` FOREIGN KEY (`report_id`) REFERENCES `monthly_reports` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '报告成就表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of report_achievements
-- ----------------------------
